/** Hard cap on focus structures. Enforces the product rule: always a bounded
 *  REGION, never the whole model. */
export const MAX_REGION_PARTS = 60;

/** Per-detail-level context tuning: how many nearest neighbours to pull per
 *  focus part, and the total context cap. */
const DETAIL_TUNING: Record<RegionDetail, { perPart: number; cap: number }> = {
  isolated: { perPart: 0, cap: 0 },
  related: { perPart: 6, cap: 14 },
  regional: { perPart: 14, cap: 30 },
};

export interface BuildRegionResult {
  payload: RegionPayload;
  summary: string;
}

export interface BuildRegionOptions {
  title?: string;
  detail?: RegionDetail;
}

/** Resolve queries into a bounded RegionPayload, optionally adding surrounding
 *  context structures (nearest neighbours) at higher detail levels. */
export function buildRegion(
  catalog: PartsCatalog,
  queries: string[],
  assetBase: string,
  opts: BuildRegionOptions = {},
): BuildRegionResult {
  const detail: RegionDetail = opts.detail ?? 'isolated';
  const focus: RegionPart[] = [];
  const seen = new Set<string>();
  const unmatched: string[] = [];
  const expanded: NonNullable<RegionPayload['expanded']> = [];
  const issues: NonNullable<RegionPayload['issues']> = [];
  let truncated = false;

  for (const raw of queries) {
    const query = (raw ?? '').trim();
    if (!query) continue;
    const resolved = resolveQueryToParts(catalog, query);
    if (!resolved) {
      unmatched.push(query);
      continue;
    }
    if (resolved.issue) {
      issues.push({ query, ...resolved.issue });
      continue;
    }
    if (resolved.expanded) {
      expanded.push({ query, label: resolved.expanded.label, count: resolved.expanded.count });
    }
    for (const p of resolved.parts) {
      if (seen.has(p.id)) continue;
      if (focus.length >= MAX_REGION_PARTS) {
        truncated = true;
        break;
      }
      seen.add(p.id);
      focus.push({
        id: p.id, // raw id — must match the GLB node name
        name_en: cleanName(p.name_en),
        name_lat: cleanName(p.name_lat),
        system: p.system,
        side: p.side,
      });
    }
    if (truncated) break;
  }

  const payload = assembleRegion(catalog, focus, assetBase, {
    detail,
    title: opts.title,
    unmatched,
    expanded,
    issues,
  });

  const focusCount = payload.parts.filter((p) => !p.context).length;
  const contextCount = payload.parts.filter((p) => p.context).length;
  const summary = buildSummary(payload, focusCount, contextCount, truncated);
  return { payload, summary };
}

export interface AssembleRegionOptions {
  detail: RegionDetail;
  title?: string;
  unmatched?: string[];
  expanded?: RegionPayload['expanded'];
  issues?: RegionPayload['issues'];
}

/** Assemble a bounded RegionPayload from ALREADY-RESOLVED focus parts: dedupe + cap the
 *  focus, add surrounding context (nearest neighbours) for related/regional detail, and
 *  build the systems + title. Shared by buildRegion (server) and the widget's live
 *  client-side recompute (detail switch / add / remove). Focus parts are assumed already
 *  cleaned (see cleanName); only freshly-pulled context parts are cleaned here. */
export function assembleRegion(
  catalog: PartsCatalog,
  focusParts: RegionPart[],
  assetBase: string,
  opts: AssembleRegionOptions,
): RegionPayload {
  const detail = opts.detail;
  const parts: RegionPart[] = [];
  const seen = new Set<string>();

  for (const p of focusParts) {
    if (seen.has(p.id)) continue;
    if (parts.length >= MAX_REGION_PARTS) break;
    seen.add(p.id);
    // Drop any stray context flag — these are focus structures.
    parts.push({
      id: p.id,
      name_en: p.name_en,
      name_lat: p.name_lat,
      system: p.system,
      side: p.side,
    });
  }

  // Surrounding context (structures the focus parts pass through / near).
  const focusIds = parts.map((p) => p.id);
  const tuning = DETAIL_TUNING[detail];
  if (tuning.perPart > 0 && focusIds.length > 0) {
    const ctx = contextFor(catalog, focusIds, tuning.perPart, tuning.cap);
    for (const p of ctx) {
      if (seen.has(p.id)) continue;
      seen.add(p.id);
      parts.push({
        id: p.id,
        name_en: cleanName(p.name_en),
        name_lat: cleanName(p.name_lat),
        system: p.system,
        side: p.side,
        context: true,
      });
    }
  }

/** Surrounding-context structures for a set of focus parts: the nearest
 *  precomputed neighbours (by AABB-to-AABB distance) across all systems —
 *  i.e. the structures each focus part passes through / runs near. Ranked by
 *  closest-to-any-focus, de-duped, excluding the focus set, capped.
 *  Returns [] if the neighbour map hasn't been primed yet. */
export function contextFor(
  catalog: PartsCatalog,
  focusIds: string[],
  perPart: number,
  cap: number,
): Part[] {
  const neighbors = cache ?? {};
  const index = getPartIndex(catalog);
  const focus = new Set(focusIds);

  // neighbour id → best (smallest) rank across all focus parts
  const bestRank = new Map<string, number>();
  for (const fid of focusIds) {
    const list = neighbors[fid];
    if (!list) continue;
    const take = list.slice(0, perPart);
    take.forEach((n, rank) => {
      if (focus.has(n.id)) return;
      const prev = bestRank.get(n.id);
      if (prev === undefined || rank < prev) bestRank.set(n.id, rank);
    });
  }

  const ranked = [...bestRank.entries()].sort((a, b) => a[1] - b[1]);
  const out: Part[] = [];
  for (const [id] of ranked) {
    const part = index.get(id);
    if (!part) continue; // not in catalog (e.g. degenerate/".g")
    out.push(part);
    if (out.length >= cap) break;
  }
  return out;

import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import test from 'node:test';
import { buildRegion } from '../src/region.js';
import type { PartsCatalog } from '../src/vendor/types.js';

const catalog = JSON.parse(readFileSync(new URL('../assets/parts-catalog.json', import.meta.url), 'utf8')) as PartsCatalog;

function resolve(query: string) {
  return buildRegion(catalog, [query], 'test', { detail: 'isolated' }).payload;
}

test('generic carotid is declined as ambiguous instead of selecting a branch', () => {
  const payload = resolve('carotid artery');
  assert.equal(payload.parts.length, 0);
  assert.deepEqual(payload.unmatched, []);
  assert.equal(payload.issues?.[0]?.kind, 'ambiguous');
  assert.match(payload.issues?.[0]?.message ?? '', /common, internal, or external/i);
});

test('unsided carotid branches are declined instead of mixing sides', () => {
  for (const query of ['common carotid artery', 'internal carotid artery', 'external carotid artery']) {
    const payload = resolve(query);
    assert.equal(payload.parts.length, 0);
    assert.deepEqual(payload.unmatched, []);
    assert.equal(payload.issues?.[0]?.kind, 'ambiguous');
    assert.deepEqual(payload.issues?.[0]?.options?.map((option) => option.split(' ')[0]), ['left', 'right']);
  }
});

test('Latin Cor expands to heart chambers and never resolves to Cornea', () => {
  const payload = resolve('Cor');
  assert.deepEqual(new Set(payload.parts.map((part) => part.name_en)), new Set(['Right atrium', 'Left atrium', 'Right ventricle', 'Left ventricle']));
  assert.equal(payload.parts.some((part) => part.name_en === 'Cornea'), false);
  assert.equal(payload.expanded?.[0]?.label, 'Heart (four chambers)');
});

test('heart expands to an explicit bounded four-chamber composite', () => {
  const payload = resolve('heart');
  assert.equal(payload.parts.length, 4);
  assert.equal(payload.expanded?.[0]?.label, 'Heart (four chambers)');
});

test('sternum expands to manubrium, body, and xiphoid process', () => {
  const payload = resolve('sternum');
  assert.deepEqual(new Set(payload.parts.map((part) => part.name_en)), new Set(['Manubrium of sternum', 'Body of sternum', 'Xiphoid process']));
});

test('femoral neck and Latin synonym are explicitly unavailable', () => {
  for (const query of ['femoral neck', 'neck of femur', 'Collum femoris']) {
    const payload = resolve(query);
    assert.equal(payload.parts.length, 0);
    assert.equal(payload.issues?.[0]?.kind, 'unavailable');
  }
});

test('invented ligament remains unmatched without substitution', () => {
  const payload = resolve('ligamentum pitlovicense');
  assert.equal(payload.parts.length, 0);
  assert.deepEqual(payload.unmatched, ['ligamentum pitlovicense']);
  assert.equal(payload.issues, undefined);
});

